package tariff

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package tariff 是本地费率版本与报价的本地基线。
package tariff

// Ready 表示基线可以运行。
func Ready() bool { return true }

